mapper.update:
update seckill_order_outbox
set status = case when retry_count + 1 >= #{maxRetry} then 3 else 2 end,
    retry_count = retry_count + 1,
    next_retry_time = case when retry_count + 1 >= #{maxRetry}
        then null
        else date_add(now(), interval #{retryDelaySeconds} second)
    end,
    error_message = #{errorMessage},
    update_time = now()
where message_id = #{messageId}
  and status != 1

mapper.select:
select id, message_id, route_key, topic, message_body, status, retry_count,
       next_retry_time, error_message, trace_id, create_time, update_time
from seckill_order_outbox


        status = #{status}


order by update_time desc, id desc
limit #{limit}
